function formatAssetName(s){return(s.substring(0,s.lastIndexOf("."))||s).split(/[-_]/).map(s=>{const e=s.toLowerCase();return"ssh"===e||"ss"===e?"SS":"rx"===e?"Rx":s.charAt(0).toUpperCase()+s.slice(1)}).join(" ")}function getAssetMeta(s){const e=s.split(".").pop().toLowerCase();return"svg"===e?"Vector SVG · Scalable Resolution":"png"===e?"PNG Image · High Definition":"jpg"===e||"jpeg"===e?"JPEG Image · Compressed Layout":"Asset File"}function getTagClass(s){const e=s.toLowerCase();return e.includes("clinic")?"tag-clinic":e.includes("wellness")||e.includes("supplement")?"tag-wellness":e.includes("ecom")||e.includes("groom")?"tag-ecom":"tag-ss"}function getTagIcon(s){const e=s.toLowerCase();return e.includes("clinic")?'<i class="fa-solid fa-stethoscope me-1"></i>':e.includes("wellness")||e.includes("supplement")?'<i class="fa-solid fa-capsules me-1"></i>':e.includes("ecom")||e.includes("groom")?'<i class="fa-solid fa-shopping-bag me-1"></i>':'<i class="fa-solid fa-circle-nodes me-1"></i>'}